type Config struct {
	OpenAIAPIKey      string                       `json:"openai_api_key,omitempty"`
	GeminiAPIKey      string                       `json:"gemini_api_key,omitempty"`
	Timeout           time.Duration                `json:"timeout"`
	DefaultProvider   string                       `json:"default_provider"`
