MODULE_PATH := $(shell sed -n 's/^module //p' go.mod 2>/dev/null | head -n1)
APP_NAME ?= $(notdir $(MODULE_PATH))
APP_ID ?= $(if $(APP_NAME),com.vitovt.$(APP_NAME),)
MAIN_PKG ?= ./cmd/app
MAIN_PKG_REL := $(patsubst ./%,%,$(MAIN_PKG))

BUILD_DIR ?= build
