	settingsErr := u.settingsValidationError()
	processErr := u.processValidationError()

	if u.running || settingsErr != nil {
		u.saveButton.Disable()
	} else {
		u.saveButton.Enable()
	}
	if u.running || processErr != nil {
		u.processButton.Disable()
	} else {
		u.processButton.Enable()
	}

	switch {
	case u.running:
