					},
					{
						Type:     "input_image",
						ImageURL: "data:" + inputImage.MIMEType + ";base64," + base64.StdEncoding.EncodeToString(inputImage.Bytes),
						Detail:   openAIImageDetail(p.cfg.AdvancedOptions),
					},
				},
			},
