	cfg, err := u.configFromWidgets()
	if err != nil {
		cfg = u.cfg
	}
	models := u.application.SupportedModels(u.providerSelect.Selected, cfg.ProviderConfig(u.providerSelect.Selected, u.modelSelect.Selected))
