func TestApplyEnvOverridesDefaults(t *testing.T) {
	cfg := Default()
	env := map[string]string{
		EnvPrefix + "DEFAULT_PROVIDER":  "gemini",
		EnvPrefix + "DEFAULT_FONT_SIZE": "22.5",
