			Width:          300,
			Height:         100,
			FontSize:       24,
			Align:          domain.TextAlignCenter,
		}},
	}

	output, err := r.Render(context.Background(), page, base.DefaultRenderOptions())
	if err != nil {
		t.Fatalf("Render() error = %v", err)
	}
	content := string(output)
	for _, fragment := range []string{
		"<office:document",
		"<draw:page",
		"<draw:image",
		"<office:binary-data>",
		"<draw:text-box>",
		"Hallo",
