package config

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"godocmirrortranslator/internal/provider"
	base "godocmirrortranslator/internal/renderer"
)

const (
	EnvPrefix         = "GODOCMIRRORTRANSLATOR_"
	ConfigPathEnv     = EnvPrefix + "CONFIG"
	defaultConfigDir  = "handwritten-overlay-translator"
	guiPrefLayoutJSON = "save_layout_json"
)

type Config struct {
	OpenAIAPIKey      string                       `json:"openai_api_key,omitempty"`
	GeminiAPIKey      string                       `json:"gemini_api_key,omitempty"`
	Timeout           time.Duration                `json:"timeout"`
	DefaultProvider   string                       `json:"default_provider"`
	DefaultRenderer   string                       `json:"default_renderer"`
	DefaultModel      string                       `json:"default_model,omitempty"`
	DefaultOutputDir  string                       `json:"default_output_dir,omitempty"`
	DefaultFontFamily string                       `json:"default_font_family"`
	DefaultFontSize   float64                      `json:"default_font_size"`
	OutputTemplate    string                       `json:"output_template"`
	OverlayColor      string                       `json:"overlay_color"`
	OverlayOpacity    float64                      `json:"overlay_opacity"`
	PreserveColumns   bool                         `json:"preserve_columns"`
	SourceLanguage    string                       `json:"source_language"`
	TargetLanguage    string                       `json:"target_language"`
	ProviderOptions   map[string]map[string]string `json:"provider_options,omitempty"`
	GUIPreferences    map[string]string            `json:"gui_preferences,omitempty"`
}

func Default() Config {
	return Config{
		Timeout:           30 * time.Second,
		DefaultProvider:   "mock",
		DefaultRenderer:   "svg",
		DefaultFontFamily: "Noto Sans",
		DefaultFontSize:   18,
		OutputTemplate:    "{input_basename}_{provider}_{timestamp}.svg",
		OverlayColor:      "#111111",
		OverlayOpacity:    1,
		SourceLanguage:    "Ukrainian",
		TargetLanguage:    "German",
		ProviderOptions:   map[string]map[string]string{},
		GUIPreferences:    map[string]string{},
	}
}

func ResolvePath(explicit string) (string, error) {
	if explicit != "" {
		return explicit, nil
	}
	if fromEnv := os.Getenv(ConfigPathEnv); fromEnv != "" {
		return fromEnv, nil
	}
	userConfigDir, err := os.UserConfigDir()
	if err != nil {
		return "", fmt.Errorf("resolve user config dir: %w", err)
	}
	return filepath.Join(userConfigDir, defaultConfigDir, "config.json"), nil
}

func Load(path string) (Config, string, error) {
	resolvedPath, err := ResolvePath(path)
	if err != nil {
		return Config{}, "", err
	}

	cfg := Default()
	data, err := os.ReadFile(resolvedPath)
	if err != nil {
		if os.IsNotExist(err) {
			return cfg, resolvedPath, nil
		}
		return Config{}, "", fmt.Errorf("read config: %w", err)
	}
	if len(data) == 0 {
		return cfg, resolvedPath, nil
	}
	if err := json.Unmarshal(data, &cfg); err != nil {
		return Config{}, "", fmt.Errorf("decode config: %w", err)
	}
	cfg.normalize()
	return cfg, resolvedPath, nil
}

func LoadEffective(path string) (Config, string, error) {
	cfg, resolvedPath, err := Load(path)
	if err != nil {
		return Config{}, "", err
	}
	if err := cfg.ApplyEnv(os.LookupEnv); err != nil {
		return Config{}, "", err
	}
	cfg.normalize()
	return cfg, resolvedPath, nil
}

func Save(path string, cfg Config) (string, error) {
	resolvedPath, err := ResolvePath(path)
	if err != nil {
		return "", err
	}
	cfg.normalize()
	if err := os.MkdirAll(filepath.Dir(resolvedPath), 0o755); err != nil {
		return "", fmt.Errorf("create config dir: %w", err)
	}
	data, err := json.MarshalIndent(cfg, "", "  ")
	if err != nil {
		return "", fmt.Errorf("encode config: %w", err)
	}
	if err := writeFileAtomically(resolvedPath, append(data, '\n'), 0o600); err != nil {
		return "", err
	}
	return resolvedPath, nil
}

func (c Config) Masked() Config {
	c.OpenAIAPIKey = maskSecret(c.OpenAIAPIKey)
	c.GeminiAPIKey = maskSecret(c.GeminiAPIKey)
	return c
}

func (c *Config) normalize() {
	defaults := Default()
	if c.Timeout <= 0 {
		c.Timeout = defaults.Timeout
	}
	if c.DefaultProvider == "" {
		c.DefaultProvider = defaults.DefaultProvider
	}
	if c.DefaultRenderer == "" {
		c.DefaultRenderer = defaults.DefaultRenderer
	}
	if c.DefaultFontFamily == "" {
		c.DefaultFontFamily = defaults.DefaultFontFamily
	}
	if c.DefaultFontSize <= 0 {
		c.DefaultFontSize = defaults.DefaultFontSize
	}
	if c.OutputTemplate == "" {
		c.OutputTemplate = defaults.OutputTemplate
	}
	if c.OverlayColor == "" {
		c.OverlayColor = defaults.OverlayColor
	}
	if c.OverlayOpacity < 0 {
		c.OverlayOpacity = defaults.OverlayOpacity
	}
	if c.SourceLanguage == "" {
		c.SourceLanguage = defaults.SourceLanguage
	}
	if c.TargetLanguage == "" {
		c.TargetLanguage = defaults.TargetLanguage
	}
	if c.ProviderOptions == nil {
		c.ProviderOptions = map[string]map[string]string{}
	}
	if c.GUIPreferences == nil {
		c.GUIPreferences = map[string]string{}
	}
}

func (c *Config) ApplyEnv(lookup func(string) (string, bool)) error {
	stringMappings := map[string]*string{
		EnvPrefix + "OPENAI_API_KEY":      &c.OpenAIAPIKey,
		EnvPrefix + "GEMINI_API_KEY":      &c.GeminiAPIKey,
		EnvPrefix + "DEFAULT_PROVIDER":    &c.DefaultProvider,
		EnvPrefix + "DEFAULT_RENDERER":    &c.DefaultRenderer,
		EnvPrefix + "DEFAULT_MODEL":       &c.DefaultModel,
		EnvPrefix + "DEFAULT_OUTPUT_DIR":  &c.DefaultOutputDir,
		EnvPrefix + "DEFAULT_FONT_FAMILY": &c.DefaultFontFamily,
		EnvPrefix + "OUTPUT_TEMPLATE":     &c.OutputTemplate,
		EnvPrefix + "OVERLAY_COLOR":       &c.OverlayColor,
		EnvPrefix + "SOURCE_LANGUAGE":     &c.SourceLanguage,
		EnvPrefix + "TARGET_LANGUAGE":     &c.TargetLanguage,
	}
	for envKey, target := range stringMappings {
		if value, ok := lookup(envKey); ok {
			*target = value
		}
	}

	if value, ok := lookup(EnvPrefix + "TIMEOUT"); ok {
		duration, err := time.ParseDuration(value)
		if err != nil {
			return fmt.Errorf("parse %s: %w", EnvPrefix+"TIMEOUT", err)
		}
		c.Timeout = duration
	}
	if value, ok := lookup(EnvPrefix + "DEFAULT_FONT_SIZE"); ok {
		fontSize, err := strconv.ParseFloat(value, 64)
		if err != nil {
			return fmt.Errorf("parse %s: %w", EnvPrefix+"DEFAULT_FONT_SIZE", err)
		}
		c.DefaultFontSize = fontSize
	}
	if value, ok := lookup(EnvPrefix + "OVERLAY_OPACITY"); ok {
		opacity, err := strconv.ParseFloat(value, 64)
		if err != nil {
			return fmt.Errorf("parse %s: %w", EnvPrefix+"OVERLAY_OPACITY", err)
		}
		c.OverlayOpacity = opacity
	}
	if value, ok := lookup(EnvPrefix + "PRESERVE_COLUMNS"); ok {
		preserveColumns, err := strconv.ParseBool(value)
		if err != nil {
			return fmt.Errorf("parse %s: %w", EnvPrefix+"PRESERVE_COLUMNS", err)
		}
		c.PreserveColumns = preserveColumns
	}
	return nil
}

func (c *Config) Set(key, value string) error {
	normalizedKey := strings.ToLower(key)
	if strings.HasPrefix(normalizedKey, "provider_options.") {
		return c.setProviderOption(normalizedKey, value)
	}

	switch normalizedKey {
	case "openai_api_key":
		c.OpenAIAPIKey = value
	case "gemini_api_key":
		c.GeminiAPIKey = value
	case "timeout":
		duration, err := time.ParseDuration(value)
		if err != nil {
			return fmt.Errorf("parse timeout: %w", err)
		}
		c.Timeout = duration
	case "default_provider":
		c.DefaultProvider = value
	case "default_renderer":
		c.DefaultRenderer = value
	case "default_model":
		c.DefaultModel = value
	case "default_output_dir":
		c.DefaultOutputDir = value
	case "default_font_family":
		c.DefaultFontFamily = value
	case "default_font_size":
		fontSize, err := strconv.ParseFloat(value, 64)
		if err != nil {
			return fmt.Errorf("parse default_font_size: %w", err)
		}
		c.DefaultFontSize = fontSize
	case "output_template":
		c.OutputTemplate = value

package domain

import "fmt"

type PageFormat string

const (
	PageFormatA4 PageFormat = "A4"
)

type Orientation string

const (
	OrientationPortrait  Orientation = "portrait"
	OrientationLandscape Orientation = "landscape"
)

type TextAlign string

const (
	TextAlignStart  TextAlign = "start"
	TextAlignCenter TextAlign = "center"
	TextAlignEnd    TextAlign = "end"
)

const (
	DefaultLineHeight = 1.2
	DefaultOpacity    = 1.0
)

type DocumentPage struct {
	SourceImagePath   string            `json:"source_image_path"`
	SourceImageWidth  int               `json:"source_image_width"`
	SourceImageHeight int               `json:"source_image_height"`
	PageFormat        PageFormat        `json:"page_format"`
	Orientation       Orientation       `json:"orientation"`
	Blocks            []TextBlock       `json:"blocks"`
	Metadata          map[string]string `json:"metadata,omitempty"`
}

type TextBlock struct {
	ID             string    `json:"id"`
	SourceText     string    `json:"source_text"`
	TranslatedText string    `json:"translated_text"`
	X              float64   `json:"x"`
	Y              float64   `json:"y"`
	Width          float64   `json:"width"`
	Height         float64   `json:"height"`
	Rotation       float64   `json:"rotation,omitempty"`
	FontSize       float64   `json:"font_size,omitempty"`
	FontFamily     string    `json:"font_family,omitempty"`
	Align          TextAlign `json:"align,omitempty"`
	Color          string    `json:"color,omitempty"`
	Opacity        float64   `json:"opacity,omitempty"`
	LineHeight     float64   `json:"line_height,omitempty"`
	Confidence     *float64  `json:"confidence,omitempty"`
	Notes          string    `json:"notes,omitempty"`
}

func (p *DocumentPage) Normalize() {
	if p.PageFormat == "" {
		p.PageFormat = PageFormatA4
	}
	if p.Orientation == "" {
		if p.SourceImageWidth > p.SourceImageHeight {
			p.Orientation = OrientationLandscape
		} else {
			p.Orientation = OrientationPortrait
		}
	}
	if p.Metadata == nil {
		p.Metadata = map[string]string{}
	}
	for i := range p.Blocks {
		if p.Blocks[i].ID == "" {
			p.Blocks[i].ID = fmt.Sprintf("block-%d", i+1)
		}
		p.Blocks[i].Normalize()
	}
}

func (p DocumentPage) Validate() error {
	if p.SourceImagePath == "" {
		return fmt.Errorf("source image path is required")
	}
	if p.SourceImageWidth <= 0 || p.SourceImageHeight <= 0 {
		return fmt.Errorf("source image dimensions must be positive")
	}
	if p.PageFormat != "" && p.PageFormat != PageFormatA4 {
		return fmt.Errorf("unsupported page format %q", p.PageFormat)
	}
	switch p.Orientation {
	case "", OrientationPortrait, OrientationLandscape:
	default:
		return fmt.Errorf("unsupported orientation %q", p.Orientation)
	}
	for i, block := range p.Blocks {
		if err := block.Validate(); err != nil {
			return fmt.Errorf("block %d: %w", i, err)
		}
	}
	return nil
}

func (b *TextBlock) Normalize() {
	if b.LineHeight <= 0 {
		b.LineHeight = DefaultLineHeight
	}
	if b.Opacity == 0 {
		b.Opacity = DefaultOpacity
	}
	if b.Align == "" {
		b.Align = TextAlignStart
	}
}

func (b TextBlock) Validate() error {
	if b.SourceText == "" {
		return fmt.Errorf("source text is required")
	}
	if b.Width < 0 || b.Height < 0 {
		return fmt.Errorf("block dimensions must be non-negative")
	}
	if b.Opacity < 0 || b.Opacity > 1 {
		return fmt.Errorf("opacity must be between 0 and 1")
	}
	if b.LineHeight < 0 {
		return fmt.Errorf("line height must be non-negative")
	}
	switch b.Align {
	case "", TextAlignStart, TextAlignCenter, TextAlignEnd:
	default:
		return fmt.Errorf("unsupported alignment %q", b.Align)
	}
	if b.Confidence != nil && (*b.Confidence < 0 || *b.Confidence > 1) {
		return fmt.Errorf("confidence must be between 0 and 1")
	}
	return nil
}

package svg

import (
	"context"
	"encoding/base64"
	"fmt"
	"html"
	"net/http"
	"os"
	"strings"

	"godocmirrortranslator/internal/domain"
	base "godocmirrortranslator/internal/renderer"
)

type Renderer struct{}

func New() *Renderer {
	return &Renderer{}
}

func (r *Renderer) Name() string {
	return "svg"
}

func (r *Renderer) FileExtension() string {
	return ".svg"
}

func (r *Renderer) Render(ctx context.Context, page *domain.DocumentPage, opts base.RenderOptions) ([]byte, error) {
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	default:
	}

	page.Normalize()
	if err := page.Validate(); err != nil {
		return nil, fmt.Errorf("validate page: %w", err)
	}
	opts = opts.Normalized()

	imageBytes, err := os.ReadFile(page.SourceImagePath)
	if err != nil {
		return nil, fmt.Errorf("read source image: %w", err)
	}

	pageWidth, pageHeight := base.A4Dimensions(page.Orientation)
	scale := base.FitScale(pageWidth, pageHeight, float64(page.SourceImageWidth), float64(page.SourceImageHeight))
	imageWidth := float64(page.SourceImageWidth) * scale
	imageHeight := float64(page.SourceImageHeight) * scale
	offsetX := (pageWidth - imageWidth) / 2
	offsetY := (pageHeight - imageHeight) / 2
	mimeType := http.DetectContentType(imageBytes)

	var b strings.Builder
	b.WriteString("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n")
	b.WriteString(fmt.Sprintf("<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" width=\"%.2fmm\" height=\"%.2fmm\" viewBox=\"0 0 %.2f %.2f\">\n", pageWidth, pageHeight, pageWidth, pageHeight))
	b.WriteString(fmt.Sprintf("  <image x=\"%.4f\" y=\"%.4f\" width=\"%.4f\" height=\"%.4f\" href=\"data:%s;base64,%s\" />\n", offsetX, offsetY, imageWidth, imageHeight, mimeType, base64.StdEncoding.EncodeToString(imageBytes)))

	for _, block := range page.Blocks {
		text := block.TranslatedText
		if text == "" {
			text = block.SourceText
		}
		fontFamily := block.FontFamily
		if fontFamily == "" {
			fontFamily = opts.FontFamily
		}
		fontSize := block.FontSize * scale
		if fontSize <= 0 {
			fontSize = opts.DefaultFontSize * scale
		}
		if fontSize < 2.5 {
			fontSize = 2.5
		}
		color := block.Color
		if color == "" {
			color = opts.TextColor
		}
		opacity := block.Opacity
		if block.Opacity == 0 && opts.HasOpacity {
			opacity = opts.Opacity
		}
		lineHeight := block.LineHeight
		if lineHeight <= 0 {
			lineHeight = domain.DefaultLineHeight
		}
		x := offsetX + (block.X * scale)
		switch block.Align {
		case domain.TextAlignCenter:
			x += (block.Width * scale) / 2
		case domain.TextAlignEnd:
			x += block.Width * scale
		}
		y := offsetY + (block.Y * scale)
		anchor := textAnchor(block.Align)
		transform := ""
		if block.Rotation != 0 {
			transform = fmt.Sprintf(" transform=\"rotate(%.4f %.4f %.4f)\"", block.Rotation, x, y)
		}
		b.WriteString(fmt.Sprintf("  <text x=\"%.4f\" y=\"%.4f\" font-family=\"%s\" font-size=\"%.4f\" fill=\"%s\" fill-opacity=\"%.4f\" text-anchor=\"%s\"%s>\n", x, y, html.EscapeString(fontFamily), fontSize, html.EscapeString(color), opacity, anchor, transform))
		for i, line := range strings.Split(text, "\n") {
			if i == 0 {
				b.WriteString(fmt.Sprintf("    <tspan x=\"%.4f\" dy=\"0\">%s</tspan>\n", x, html.EscapeString(line)))
				continue
			}
			b.WriteString(fmt.Sprintf("    <tspan x=\"%.4f\" dy=\"%.4f\">%s</tspan>\n", x, fontSize*lineHeight, html.EscapeString(line)))
		}
		b.WriteString("  </text>\n")
	}

	b.WriteString("</svg>\n")
	return []byte(b.String()), nil
}

func textAnchor(align domain.TextAlign) string {
	switch align {
	case domain.TextAlignCenter:
		return "middle"
	case domain.TextAlignEnd:
		return "end"
	default:
		return "start"
	}
}

