package app

import (
	"context"
	"encoding/binary"
	"encoding/json"
	"fmt"
	"image"
	_ "image/jpeg"
	_ "image/png"
	"io"
	"os"
	"path/filepath"
	"strings"
	"time"

	"godocmirrortranslator/internal/provider"
	base "godocmirrortranslator/internal/renderer"
)

const DefaultOutputTemplate = "{input_basename}_{provider}_{timestamp}.svg"

var atomicWriteFile = writeAtomically
var knownRendererExtensions = []string{".svg", ".fodg"}

type RenderRequest struct {
	InputPath      string
	OutputDir      string
	OutputTemplate string
	ProviderName   string
	ProviderConfig provider.ProviderConfig
	RendererName   string
	Model          string
	SourceLanguage string
	TargetLanguage string
	Timeout        time.Duration
	SaveLayoutJSON bool
	RenderOptions  base.RenderOptions
	Now            func() time.Time
}

type RenderResult struct {
	OutputPath     string
	LayoutJSONPath string
}

func (a *Application) RunRender(ctx context.Context, stdout io.Writer, req RenderRequest) error {
	result, err := a.Render(ctx, req)
	if err != nil {
		return err
	}
	_, err = fmt.Fprintln(stdout, result.OutputPath)
	return err
}

func (a *Application) ValidateInputImage(path string) error {
	_, _, err := validateInputImage(path)
	return err
}

func (a *Application) Render(ctx context.Context, req RenderRequest) (RenderResult, error) {
	if req.InputPath == "" {
		return RenderResult{}, fmt.Errorf("input path is required")
	}
	if req.ProviderName == "" {
		req.ProviderName = "mock"
	}
	if req.RendererName == "" {
		req.RendererName = "svg"
	}
	if req.SourceLanguage == "" {
		req.SourceLanguage = "Ukrainian"
	}
	if req.TargetLanguage == "" {
		req.TargetLanguage = "German"
	}
	if req.OutputTemplate == "" {
		req.OutputTemplate = DefaultOutputTemplate
	}
	if req.Now == nil {
		req.Now = time.Now
	}
	if req.Timeout <= 0 {
		req.Timeout = 30 * time.Second
	}
	if req.OutputDir == "" {
		req.OutputDir = filepath.Dir(req.InputPath)
	}

	providerFactory, ok := a.ProviderFactories[req.ProviderName]
	if !ok {
		return RenderResult{}, fmt.Errorf("unknown provider %q", req.ProviderName)
	}
	providerImpl := providerFactory(req.ProviderConfig)
	if err := providerImpl.ValidateConfig(req.ProviderConfig); err != nil {
		return RenderResult{}, fmt.Errorf("validate provider config: %w", err)
	}
	rendererImpl, ok := a.Renderers[req.RendererName]
	if !ok {
		return RenderResult{}, fmt.Errorf("unknown renderer %q", req.RendererName)
	}

	imageWidth, imageHeight, err := validateInputImage(req.InputPath)
	if err != nil {
		return RenderResult{}, err
	}

	renderCtx, cancel := context.WithTimeout(ctx, req.Timeout)
	defer cancel()

	page, err := providerImpl.AnalyzePage(renderCtx, provider.AnalyzeRequest{
		ImagePath:         req.InputPath,
		SourceImageWidth:  imageWidth,
		SourceImageHeight: imageHeight,
		SourceLanguage:    req.SourceLanguage,
		TargetLanguage:    req.TargetLanguage,
		Model:             req.Model,
		Timeout:           req.Timeout,
	})
	if err != nil {
		return RenderResult{}, fmt.Errorf("analyze page: %w", err)
	}
	page.Normalize()
	if err := page.Validate(); err != nil {
		return RenderResult{}, fmt.Errorf("validate provider output: %w", err)
	}

	renderBytes, err := rendererImpl.Render(renderCtx, page, req.RenderOptions)
	if err != nil {
		return RenderResult{}, fmt.Errorf("render output: %w", err)
	}

	outputName := outputFileName(req.OutputTemplate, req.ProviderName, req.Model, req.InputPath, req.Now(), rendererImpl.FileExtension())
	outputPath, err := availablePath(filepath.Join(req.OutputDir, outputName))
	if err != nil {
		return RenderResult{}, fmt.Errorf("choose output path: %w", err)
	}
	if err := os.MkdirAll(filepath.Dir(outputPath), 0o755); err != nil {
		return RenderResult{}, fmt.Errorf("create output directory: %w", err)
	}
	if err := atomicWriteFile(outputPath, renderBytes); err != nil {
		return RenderResult{}, fmt.Errorf("write rendered output: %w", err)
	}

	result := RenderResult{OutputPath: outputPath}
	if req.SaveLayoutJSON {
		jsonPath := strings.TrimSuffix(outputPath, filepath.Ext(outputPath)) + ".json"
		jsonBytes, err := json.MarshalIndent(page, "", "  ")
		if err != nil {
			return RenderResult{}, cleanupRenderOutputs([]string{outputPath}, fmt.Errorf("marshal layout json: %w", err))
		}
		if err := atomicWriteFile(jsonPath, append(jsonBytes, '\n')); err != nil {
			return RenderResult{}, cleanupRenderOutputs([]string{outputPath, jsonPath}, fmt.Errorf("write layout json: %w", err))
		}
		result.LayoutJSONPath = jsonPath
	}

	return result, nil
}

func validateInputImage(path string) (int, int, error) {
	info, err := os.Stat(path)
	if err != nil {
		return 0, 0, fmt.Errorf("stat input image: %w", err)
	}
	if info.Size() > 20*1024*1024 {
		return 0, 0, fmt.Errorf("input image exceeds 20 MiB")
	}
	ext := strings.ToLower(filepath.Ext(path))
	switch ext {
	case ".jpg", ".jpeg", ".png":
		file, err := os.Open(path)
		if err != nil {
			return 0, 0, fmt.Errorf("open input image: %w", err)
		}
		defer file.Close()

		cfg, _, err := image.DecodeConfig(file)
		if err != nil {
			return 0, 0, fmt.Errorf("decode input image config: %w", err)
		}
		return cfg.Width, cfg.Height, nil
	case ".webp":
		data, err := os.ReadFile(path)
		if err != nil {
			return 0, 0, fmt.Errorf("read input image: %w", err)
		}
		width, height, err := decodeWebPDimensions(data)
		if err != nil {
			return 0, 0, fmt.Errorf("decode webp dimensions: %w", err)
		}
		return width, height, nil
	default:
		return 0, 0, fmt.Errorf("unsupported image format %q", ext)
	}
}

func decodeWebPDimensions(data []byte) (int, int, error) {
	if len(data) < 16 || string(data[0:4]) != "RIFF" || string(data[8:12]) != "WEBP" {
		return 0, 0, fmt.Errorf("invalid webp header")
	}
	chunk := string(data[12:16])
	switch chunk {
	case "VP8X":
		if len(data) < 30 {
			return 0, 0, fmt.Errorf("truncated VP8X header")
		}
		widthMinusOne := int(data[24]) | int(data[25])<<8 | int(data[26])<<16
		heightMinusOne := int(data[27]) | int(data[28])<<8 | int(data[29])<<16
		return widthMinusOne + 1, heightMinusOne + 1, nil
	case "VP8L":
		if len(data) < 25 {
			return 0, 0, fmt.Errorf("truncated VP8L header")
		}
		bits := binary.LittleEndian.Uint32(data[21:25])
		width := int(bits&0x3FFF) + 1
		height := int((bits>>14)&0x3FFF) + 1
		return width, height, nil
	case "VP8 ":
		if len(data) < 30 {
			return 0, 0, fmt.Errorf("truncated VP8 header")
		}
		width := int(binary.LittleEndian.Uint16(data[26:28]) & 0x3FFF)
		height := int(binary.LittleEndian.Uint16(data[28:30]) & 0x3FFF)
		if width == 0 || height == 0 {
			return 0, 0, fmt.Errorf("invalid VP8 dimensions")
		}
		return width, height, nil
	default:
		return 0, 0, fmt.Errorf("unsupported webp chunk %q", chunk)
	}
}

func outputFileName(template, providerName, model, inputPath string, now time.Time, extension string) string {
	name := template
	baseName := strings.TrimSuffix(filepath.Base(inputPath), filepath.Ext(inputPath))
	replacements := map[string]string{
		"{input_basename}": baseName,
		"{provider}":       providerName,
		"{model}":          model,
		"{date}":           now.Format("2006-01-02"),
		"{time}":           now.Format("15-04-05"),
		"{timestamp}":      now.Format("20060102-150405"),
	}
	for key, value := range replacements {
		name = strings.ReplaceAll(name, key, value)
	}
	lowerName := strings.ToLower(name)
	lowerExtension := strings.ToLower(extension)
	if strings.HasSuffix(lowerName, lowerExtension) {
		return name
	}
	for _, known := range knownRendererExtensions {
		if strings.HasSuffix(lowerName, known) {
			return name[:len(name)-len(known)] + extension
		}
	}
	return name + extension
}

func availablePath(path string) (string, error) {
	if _, err := os.Stat(path); os.IsNotExist(err) {
		return path, nil
	} else if err != nil {
		return "", err
	}
	ext := filepath.Ext(path)
	stem := strings.TrimSuffix(path, ext)
	for i := 1; ; i++ {
		candidate := fmt.Sprintf("%s-%d%s", stem, i, ext)
		if _, err := os.Stat(candidate); os.IsNotExist(err) {
			return candidate, nil
		} else if err != nil {
			return "", err
		}
	}
}

func writeAtomically(path string, data []byte) error {
	temp, err := os.CreateTemp(filepath.Dir(path), ".tmp-*")

package cli

import (
	"context"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"strings"

	"godocmirrortranslator/internal/app"
	"godocmirrortranslator/internal/config"
	"godocmirrortranslator/internal/gui"
)

const Version = "dev"

func Run(ctx context.Context, args []string, stdout io.Writer, stderr io.Writer) int {
	application := app.New(Version)

	if len(args) == 0 {
		printHelp(stdout)
		return 0
	}

	switch args[0] {
	case "render":
		return runRender(ctx, application, args[1:], stdout, stderr)
	case "providers":
		if len(args) > 1 && args[1] == "list" {
			for _, name := range application.ProviderNames() {
				_, _ = fmt.Fprintln(stdout, name)
			}
			return 0
		}
	case "version":
		_, _ = fmt.Fprintln(stdout, Version)
		return 0
	case "gui":
		return runGUI(ctx, application, args[1:], stderr)
	case "config":
		return runConfig(args[1:], stdout, stderr)
	case "help", "--help", "-h":
		printHelp(stdout)
		return 0
	}

	_, _ = fmt.Fprintf(stderr, "unknown command: %s\n", strings.Join(args, " "))
	printHelp(stderr)
	return 1
}

func runGUI(ctx context.Context, application *app.Application, args []string, stderr io.Writer) int {
	fs := flag.NewFlagSet("gui", flag.ContinueOnError)
	fs.SetOutput(stderr)
	fs.Usage = func() {
		printGUIUsage(stderr, fs)
	}
	configPath := ""
	fs.StringVar(&configPath, "config", "", "Optional config file path")
	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return 0
		}
		return 2
	}
	if err := gui.Run(ctx, application, Version, configPath); err != nil {
		_, _ = fmt.Fprintf(stderr, "gui: %v\n", err)
		return 1
	}
	return 0
}

func runRender(ctx context.Context, application *app.Application, args []string, stdout io.Writer, stderr io.Writer) int {
	showHelpOnly := hasHelpFlag(args)
	configPath := ""
	for i := 0; i < len(args); i++ {
		if args[i] == "--config" {
			if i+1 < len(args) {
				configPath = args[i+1]
			}
			continue
		}
		if strings.HasPrefix(args[i], "--config=") {
			configPath = strings.TrimPrefix(args[i], "--config=")
		}
	}

	cfg := config.Default()
	if !showHelpOnly {
		var err error
		cfg, _, err = config.LoadEffective(configPath)
		if err != nil {
			_, _ = fmt.Fprintf(stderr, "render: load config: %v\n", err)
			return 1
		}
	}

	req := app.RenderRequest{
		OutputDir:      cfg.DefaultOutputDir,
		OutputTemplate: cfg.OutputTemplate,
		ProviderName:   cfg.DefaultProvider,
		RendererName:   cfg.DefaultRenderer,
		Model:          cfg.DefaultModel,
		SourceLanguage: cfg.SourceLanguage,
		TargetLanguage: cfg.TargetLanguage,
		Timeout:        cfg.Timeout,
		RenderOptions:  cfg.RenderOptions(),
	}

	fs := flag.NewFlagSet("render", flag.ContinueOnError)
	fs.SetOutput(stderr)
	fs.Usage = func() {
		printRenderUsage(stderr, fs)
	}

	fs.StringVar(&req.InputPath, "input", req.InputPath, "Path to the input image")
	fs.StringVar(&req.OutputDir, "output-dir", req.OutputDir, "Directory for generated files")
	fs.StringVar(&req.OutputTemplate, "output-template", req.OutputTemplate, "Filename template for rendered output")
	fs.StringVar(&req.ProviderName, "provider", req.ProviderName, "Provider to use")
	fs.StringVar(&req.RendererName, "renderer", req.RendererName, "Renderer to use")
	fs.StringVar(&req.Model, "model", req.Model, "Model to use")
	fs.StringVar(&req.SourceLanguage, "source-lang", req.SourceLanguage, "Source language")
	fs.StringVar(&req.TargetLanguage, "target-lang", req.TargetLanguage, "Target language")
	fs.StringVar(&req.RenderOptions.FontFamily, "font-family", req.RenderOptions.FontFamily, "Fallback font family")
	fs.Float64Var(&req.RenderOptions.DefaultFontSize, "font-size", req.RenderOptions.DefaultFontSize, "Fallback font size")
	fs.Float64Var(&req.RenderOptions.Opacity, "opacity", req.RenderOptions.Opacity, "Fallback text opacity")
	fs.StringVar(&req.RenderOptions.TextColor, "color", req.RenderOptions.TextColor, "Fallback text color")
	fs.DurationVar(&req.Timeout, "timeout", req.Timeout, "Provider request timeout")
	fs.BoolVar(&req.SaveLayoutJSON, "save-layout-json", false, "Write layout JSON next to the rendered output")
	verbose := fs.Bool("verbose", false, "Print extra result information")
	fs.StringVar(&configPath, "config", configPath, "Optional config file path")

	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return 0
		}
		return 2
	}
	req.ProviderConfig = cfg.ProviderConfig(req.ProviderName, req.Model)

	result, err := application.Render(ctx, req)
	if err != nil {
		_, _ = fmt.Fprintf(stderr, "render: %v\n", err)
		return 1
	}

	_, _ = fmt.Fprintln(stdout, result.OutputPath)
	if *verbose && result.LayoutJSONPath != "" {
		_, _ = fmt.Fprintf(stdout, "layout_json=%s\n", result.LayoutJSONPath)
	}
	return 0
}

func runConfig(args []string, stdout io.Writer, stderr io.Writer) int {
	if len(args) == 0 {
		printConfigUsage(stderr)
		return 0
	}
	if len(args) == 1 && hasHelpFlag(args) {
		printConfigUsage(stdout)
		return 0
	}

	switch args[0] {
	case "init":
		return runConfigInit(args[1:], stdout, stderr)
	case "get":
		return runConfigGet(args[1:], stdout, stderr)
	case "set":
		return runConfigSet(args[1:], stdout, stderr)
	default:
		_, _ = fmt.Fprintf(stderr, "unknown config subcommand: %s\n", args[0])
		return 2
	}
}

func runConfigInit(args []string, stdout io.Writer, stderr io.Writer) int {
	fs := flag.NewFlagSet("config init", flag.ContinueOnError)
	fs.SetOutput(stderr)
	fs.Usage = func() {
		printConfigInitUsage(stderr, fs)
	}
	configPath := ""
	fs.StringVar(&configPath, "config", "", "Optional config file path")
	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return 0
		}
		return 2
	}

	cfg, resolvedPath, err := config.Load(configPath)
	if err != nil {
		_, _ = fmt.Fprintf(stderr, "config init: %v\n", err)
		return 1
	}
	resolvedPath, err = config.Save(resolvedPath, cfg)
	if err != nil {
		_, _ = fmt.Fprintf(stderr, "config init: %v\n", err)
		return 1
	}
	_, _ = fmt.Fprintln(stdout, resolvedPath)
	return 0
}

func runConfigGet(args []string, stdout io.Writer, stderr io.Writer) int {
	fs := flag.NewFlagSet("config get", flag.ContinueOnError)
	fs.SetOutput(stderr)
	fs.Usage = func() {
		printConfigGetUsage(stderr, fs)
	}
	configPath := ""
	fs.StringVar(&configPath, "config", "", "Optional config file path")
	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return 0
		}
		return 2
	}

	cfg, _, err := config.LoadEffective(configPath)
	if err != nil {
		_, _ = fmt.Fprintf(stderr, "config get: %v\n", err)
		return 1
	}
	cfg = cfg.Masked()
