+func svgMetricsForBlock(block domain.TextBlock, opts base.RenderOptions, scale, offsetX, offsetY float64) svgTextMetrics {
+	text := block.TranslatedText
+	if text == "" {
+		text = block.SourceText
+	}
+
+	fontFamily := block.FontFamily
+	if fontFamily == "" {
