+	switch block.Align {
+	case domain.TextAlignCenter:
+		boxX -= boxWidth / 2
+	case domain.TextAlignEnd:
+		boxX -= boxWidth
+	}
+	boxY := y - fontSize
+
+	return svgTextMetrics{
+		Lines:      lines,
+		X:          x,
+		Y:          y,
+		BoxX:       boxX,
+		BoxY:       boxY,
+		BoxWidth:   boxWidth,
+		BoxHeight:  boxHeight,
+		FontFamily: fontFamily,
+		FontSize:   fontSize,
+		Color:      color,
+		Opacity:    opacity,
+		LineHeight: lineHeight,
+		Anchor:     anchor,
+		Transform:  transform,
+	}
+}
+
+func writeTextElement(b *strings.Builder, metrics svgTextMetrics, attrs string) {
+	b.WriteString(fmt.Sprintf("  <text x=\"%.4f\" y=\"%.4f\" font-family=\"%s\" font-size=\"%.4f\" text-anchor=\"%s\"%s%s>\n",
+		metrics.X,
+		metrics.Y,
