+func writeTextElement(b *strings.Builder, metrics svgTextMetrics, attrs string) {
+	b.WriteString(fmt.Sprintf("  <text x=\"%.4f\" y=\"%.4f\" font-family=\"%s\" font-size=\"%.4f\"%s text-anchor=\"%s\"%s>\n",
+		metrics.X,
+		metrics.Y,
+		html.EscapeString(metrics.FontFamily),
+		metrics.FontSize,
+		attrs,
+		metrics.Anchor,
+		metrics.Transform,
+	))
