+		b.WriteString(fmt.Sprintf("    <tspan x=\"%.4f\" dy=\"%.4f\">%s</tspan>\n", metrics.X, metrics.FontSize*metrics.LineHeight, html.EscapeString(line)))
+	}
+	b.WriteString("  </text>\n")
+}
