func (c Config) SaveLayoutJSONEnabled() bool {
	if c.GUIPreferences == nil {
		return false
	}
	value := strings.TrimSpace(c.GUIPreferences[guiPrefLayoutJSON])
	if value == "" {
		return false
	}
	enabled, err := strconv.ParseBool(value)
	if err != nil {
		return false
	}
	return enabled
}

func (c *Config) SetSaveLayoutJSONEnabled(enabled bool) {
	if c.GUIPreferences == nil {
		c.GUIPreferences = map[string]string{}
	}
	c.GUIPreferences[guiPrefLayoutJSON] = strconv.FormatBool(enabled)
}

func maskSecret(value string) string {
	if value == "" {
		return ""
	}
	if len(value) <= 4 {
		return "****"
	}
	return value[:2] + strings.Repeat("*", len(value)-4) + value[len(value)-2:]
}

func (c *Config) setProviderOption(key, value string) error {
	parts := strings.SplitN(key, ".", 3)
	if len(parts) != 3 || strings.TrimSpace(parts[1]) == "" || strings.TrimSpace(parts[2]) == "" {
		return fmt.Errorf("provider option key must be provider_options.<provider>.<option>")
	}
	c.normalize()
	if c.ProviderOptions[parts[1]] == nil {
		c.ProviderOptions[parts[1]] = map[string]string{}
	}
	c.ProviderOptions[parts[1]][parts[2]] = value
	return nil
}

func writeFileAtomically(path string, data []byte, perm os.FileMode) error {
	tempFile, err := os.CreateTemp(filepath.Dir(path), ".tmp-*")
	if err != nil {
		return fmt.Errorf("create temp config: %w", err)
	}
	tempName := tempFile.Name()
	defer os.Remove(tempName)

	if _, err := tempFile.Write(data); err != nil {
		_ = tempFile.Close()
		return fmt.Errorf("write temp config: %w", err)
	}
	if err := tempFile.Chmod(perm); err != nil {
		_ = tempFile.Close()
		return fmt.Errorf("chmod temp config: %w", err)
	}
	if err := tempFile.Close(); err != nil {
		return fmt.Errorf("close temp config: %w", err)
	}
	if err := os.Rename(tempName, path); err != nil {
		return fmt.Errorf("rename temp config: %w", err)
	}
	return nil
}

