		o.FontWeight = defaults.FontWeight
	}
	if o.OutlineColor == "" {
		o.OutlineColor = defaults.OutlineColor
	}
	if o.OutlineWidth < 0 {
		o.OutlineWidth = defaults.OutlineWidth
	}
	if o.BackgroundColor == "" {
		o.BackgroundColor = defaults.BackgroundColor
	}
	if o.BackgroundOpacity < 0 {
