func FitScale(pageWidth, pageHeight, sourceWidth, sourceHeight float64) float64 {
	if sourceWidth <= 0 || sourceHeight <= 0 {
		return 1
	}
	widthScale := pageWidth / sourceWidth
	heightScale := pageHeight / sourceHeight
	if widthScale < heightScale {
		return widthScale
	}
	return heightScale
}

