package main

import (
  "context"
  "fmt"
  "image"
  "image/color"
  "image/png"
  "os"
  "path/filepath"

  "godocmirrortranslator/internal/domain"
  base "godocmirrortranslator/internal/renderer"
  "godocmirrortranslator/internal/renderer/fodg"
)

func main() {
  dir, _ := os.MkdirTemp("", "fodg-check-")
  fmt.Println(dir)
  inputPath := filepath.Join(dir, "page.png")
  img := image.NewRGBA(image.Rect(0, 0, 800, 1000))
  for y := 0; y < 1000; y++ {
    for x := 0; x < 800; x++ {
      img.Set(x, y, color.RGBA{240, 240, 240, 255})
    }
  }
  f, _ := os.Create(inputPath)
  _ = png.Encode(f, img)
  _ = f.Close()
  page := &domain.DocumentPage{SourceImagePath: inputPath, SourceImageWidth: 800, SourceImageHeight: 1000, Blocks: []domain.TextBlock{{TranslatedText: "Hallo FODG", X: 100, Y: 200, Width: 300, Height: 100, FontSize: 24}}}
  out, err := fodg.New().Render(context.Background(), page, base.RenderOptions{FontFamily: "Noto Sans", DefaultFontSize: 18, TextColor: "#3366cc", Opacity: 1, HasOpacity: true, FontWeight: "bold", OutlineColor: "#ffffff", OutlineWidth: 2, BackgroundEnabled: true, BackgroundColor: "#ffffcc", BackgroundOpacity: 0.85, ShadowEnabled: true, ShadowColor: "#99cc66", ShadowOpacity: 0.65, ShadowBlur: 4, ShadowOffsetX: 2, ShadowOffsetY: 2})
  if err != nil {
    panic(err)
  }
  _ = os.WriteFile(filepath.Join(dir, "page.fodg"), out, 0o600)
}
EOF
GOCACHE=/tmp/go-build go run "$tmpfile"","workdir":"/home/vitovt/Desktop/Dev/GoDocMirrorTranslator","yield_time_ms":1000,"max_output_tokens":4000}

