 func parseFloatEntry(value string, name string) (float64, error) {
 	parsed, err := strconv.ParseFloat(strings.TrimSpace(value), 64)
 	if err != nil {
 		return 0, fmt.Errorf("%s must be numeric", name)
 	}
 	return parsed, nil
 }
