		echo "Examples:"; \
		echo "  make init PROJECTNAME=weatherchecker"; \
		echo "  make init PROJECTNAME=github.com/acme/weatherchecker"; \
		echo "  make init PROJECTNAME=gitlab.com/team/weather-tool"; \
		exit 1; \
	fi
	@if [ -z "$(MODULE_PATH)" ] || [ -z "$(APP_NAME)" ]; then \
