		exit 1; \
	fi
	@if [ -n "$$(git status --porcelain)" ]; then \
		echo "Release requires a clean git working tree."; \
		exit 1; \
	fi
	@if ! command -v gh >/dev/null 2>&1; then \
		echo "GitHub CLI (gh) is required for make release."; \
		exit 1; \
	fi
	@if ! gh auth status >/dev/null 2>&1; then \
